export function avatarCostumeVariants(player = {}) {
  const gender = player.gender === 'female' ? 'female' : 'male';
  return AVATAR_COSTUME_VARIANTS.filter(v => v.race === playerRace(player) && v.gender === gender);
}
export function avatarCostumeArtUrl(costumeId, player = {}, width = 512) {
  if (![256,512,1024].includes(width)) return null;
  const variant = avatarCostumeVariants(player).find(v => v.costumeId === costumeId);
  return variant ? '/art/avatars/collections/v1/' + variant.key + '-' + width + '.webp' : null;
}
